SELECT *
FROM categories
WHERE user_id = #{userId}
AND id = #{categoryId}

SELECT *
FROM categories
WHERE name = #{name}
AND user_id = #{userId}

mapper.update:
UPDATE categories
SET
    name = #{name},
    color = #{color}
WHERE id = #{categoryId}
    AND user_id = #{userId}
    AND is_system = 0
    AND deleted_at IS NULL

UPDATE categories
SET
    deleted_at = NULL,
    color = #{color}
WHERE id = #{categoryId}
    AND user_id = #{userId}
    AND is_system = 0
    AND deleted_at IS NOT NULL
